(4, 'CONTRAT_CONVENTION_PRET', 'Contrat / convention de prêt', 'Copie du contrat ou de la convention de prêt : ajoutée par le partenaire financier (AGR, MPE/MEPS) ou par le service garantie et contentieux (Projets structurants/Start Up)', 1, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(5, 'TABLEAU_AMORTISSEMENT', 'Tableau d\'amortissement', 'Ajouté par le partenaire financier, importable sur un modèle standard mis à disposition', 1, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(6, 'PLAN_DECAISSEMENT', 'Plan de décaissement', 'Fichier PDF du plan de décaissement signé par le bénéficiaire, saisi par le CIP (MPE/MEPS, Projets structurants/Start Up)', 1, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(7, 'JUSTIFICATIF_DECAISSEMENT', 'Justificatif de décaissement', 'Pièce jointe à chaque ligne de décaissement', 1, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(8, 'JUSTIFICATIF_REMBOURSEMENT', 'Justificatif de remboursement', 'Pièces associées à la saisie des remboursements', 1, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(9, 'RAPPORT_VISITE_SUIVI', 'Rapport de visite de suivi', 'Date, état du projet, difficultés, recommandations, position GPS, photos, fichiers multiples', 1, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
