INSERT INTO `workflow_etapes` (`id`, `workflow_version`, `parent_etape_code`, `code`, `name`, `impact`, `statut`, `description`, `order`, `is_active`, `valid_from`, `valid_to`, `created_at`, `updated_at`) VALUES
(1, 'AGR_CLASSIQUE_2026', '', 'AGRC_PRCO_1', 'RÉCUPÉRATION DES PROJETS SÉLECTIONNÉS', 'DOSSIER_RECUPERE', 'NON', 'Récupération de la liste des projets sélectionnés et pour lesquels les promoteurs ont été formés. Le rattachement à l\'agence régionale est récupéré via l\'API mise à disposition, ou à défaut déduit de la localisation du projet par région.', 1, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(2, 'AGR_CLASSIQUE_2026', '', 'AGRC_PRCO_2', 'AJOUT DES PLANS D’AFFAIRES PAR LES AGENCES RÉGIONALES', 'PLAN_AFFAIRES_AJOUTE', 'NON', 'Les chefs d\'agences régionales, conseillers en insertion pro. ou leurs assistants ajoutent le fichier du plan d\'affaires pour chaque projet, puis transmettent la liste et les fichiers au chef de service développement des ressources de financement.', 2, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(3, 'AGR_CLASSIQUE_2026', '', 'AGRC_PRCO_3', 'TRANSMISSION AU PARTENAIRE FINANCIER', 'TRANSMIS_PARTENAIRE', 'NON', 'Le chef de service développement des ressources de financement (ou un agent du service) transmet les dossiers par lot via un fichier Excel qui répartit les projets entre partenaires. Le système transfère la liste sur l\'interface du partenaire à partir du N° de dossier. Le courrier de transmission est joint et certaines de ses informations (référence, titre, date, taux de couverture, durée du différé, durée du remboursement, réf. de la convention) sont extraites et affichées sur chaque ligne de projet.', 3, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(4, 'AGR_CLASSIQUE_2026', '', 'AGRC_PRCO_4', 'TRAITEMENT DES DOSSIERS PAR LE PARTENAIRE FINANCIER', 'EN_ANALYSE_PARTENAIRE', 'NON', 'Le partenaire financier renseigne, par saisie directe ou import Excel, les informations du lot de dossiers (date d\'ouverture du compte, approbation ou non, montant du crédit, durée du prêt, taux d\'intérêt, durée du remboursement), ajoute le tableau d\'amortissement (import possible sur modèle fourni) et une copie du contrat/convention de prêt en pièce jointe. Les dossiers approuvés et les dossiers rejetés sont collectés dans deux listes distinctes puis renvoyés au chef de service développement des ressources de financement.', 4, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(5, 'AGR_CLASSIQUE_2026', '', 'AGRC_PRCO_5', 'DÉCAISSEMENT / REMBOURSEMENT', 'EN_FINANCEMENT', 'NON', 'Décaissement et suivi des remboursements des bénéficiaires par le partenaire financier.', 5, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(6, 'AGR_CLASSIQUE_2026', '', 'AGRC_PRCO_6', 'SUIVI', 'EN_SUIVI', 'NON', 'Une fois le premier décaissement effectué, les agences régionales et la DPF réalisent des visites de suivi (date de la visite, état du projet, difficultés, recommandations, position GPS, photo du lieu), avec possibilité de joindre plusieurs fichiers (rapport de visite, etc.).', 6, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(7, 'AGR_PLUS_2026', '', 'AGRP_PRCO_5', 'DEBLOCAGE DU FINANCEMENT', 'EN_DECAISSEMENT', 'NON', 'Le déblocage du financement', 1, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(8, 'AGR_PLUS_2026', '', 'AGRP_PRCO_6', 'SUIVI DES FINANCEMENTS', 'EN_SUIVI', 'NON', 'Le suivi des financements', 2, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(9, 'AGR_PLUS_2026', '', 'AGRP_PRCO_7', 'REMBOURSEMENT DU CREDIT', 'EN_REMBOURSEMENT', 'NON', 'Le remboursement du crédit', 3, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(10, 'AGR_PLUS_2026', '', 'AGRP_PRCO_8', 'EVALUATION', 'EN_EVALUATION', 'NON', 'L\'évaluation', 4, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(11, 'MPE_2026', '', 'MPE_PRCO_1', 'RÉCUPÉRATION DE LA LISTE DES PROJETS', 'DOSSIER_RECUPERE', 'NON', 'Récupération de la liste des projets sélectionnés et pour lesquels les promoteurs ont été formés. Liste disponible pour tous les profils de l\'AEJ. Le rattachement à l\'agence régionale est récupéré via l\'API mise à disposition, ou à défaut déduit de la localisation du projet par région.', 1, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(12, 'MPE_2026', '', 'MPE_PRCO_2', 'TRANSMISSION AU PARTENAIRE FINANCIER', 'TRANSMIS_PARTENAIRE', 'NON', 'Le chef de service développement des ressources de financement (ou un agent du service) ajoute le plan d\'affaires puis transmet les dossiers par lot via un fichier Excel qui répartit les projets entre partenaires. Le courrier de transmission est joint et certaines de ses informations (référence, titre, date, taux de couverture, durée du différé, durée du remboursement, réf. de la convention) sont extraites et affichées sur chaque ligne de projet.', 2, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(13, 'MPE_2026', '', 'MPE_PRCO_3', 'IMPUTATION DES DOSSIERS APPROUVÉS AUX AGENCES RÉGIONALES', 'IMPUTE_AGENCE', 'NON', 'Sur la base des dossiers approuvés par le partenaire financier, le chef de service financement et monitoring impute certains dossiers aux agences régionales selon leur localisation. Les dossiers restants non imputés sont gérés directement par la Direction pour la saisie des plans de décaissement.', 3, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(14, 'MPE_2026', '', 'MPE_PRCO_4', 'SAISIE DES PLANS DE DÉCAISSEMENT PAR LES CIP DES AGENCES RÉGIONALES', 'PLAN_DECAISSEMENT_SAISI', 'NON', 'Le conseiller en insertion professionnelle (ou un agent de la direction pour les dossiers non imputés) remplit les plans de décaissement des bénéficiaires, avec possibilité d\'ajouter une note ou observation, et joint le fichier PDF du plan de décaissement signé par le bénéficiaire. Le plan de décaissement est partagé au bénéficiaire qui le valide via l\'application mobile.', 4, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(15, 'MPE_2026', '', 'MPE_PRCO_5', 'TRANSMISSION DES DOSSIERS AVEC LES PLANS DE DÉCAISSEMENT SAISIS', 'EN_VALIDATION_INTERNE', 'NON', 'Chaîne de validation interne du plan de décaissement avant transmission au partenaire financier.', 5, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(16, 'MPE_2026', '', 'MPE_PRCO_6', 'TRAITEMENT DES DOSSIERS PAR LE PARTENAIRE', 'EN_ANALYSE_PARTENAIRE', 'NON', 'Le partenaire financier renseigne, par saisie directe ou import Excel, les informations du lot de dossiers (date d\'ouverture du compte, approbation ou non, montant du crédit, durée du prêt, taux d\'intérêt, durée du remboursement), ajoute le tableau d\'amortissement (import possible) et une copie du contrat/convention de prêt en pièce jointe. Les dossiers approuvés et rejetés sont collectés dans deux listes distinctes puis renvoyés au chef de service développement des ressources de financement. Un outil de recherche permet à toute agence ou agent de l\'AEJ de retrouver un dossier par nom, téléphone ou N° de dossier du bénéficiaire.', 6, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(17, 'MPE_2026', '', 'MPE_PRCO_7', 'DÉCAISSEMENT / REMBOURSEMENT', 'EN_FINANCEMENT', 'NON', 'Décaissement autorisé par le partenaire puis exécuté par les agences régionales, et suivi des remboursements.', 7, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(18, 'MPE_2026', '', 'MPE_PRCO_8', 'SUIVI', 'EN_SUIVI', 'NON', 'Une fois le premier décaissement effectué, les agences régionales et la DPF réalisent des visites de suivi (date de la visite, état du projet, difficultés, recommandations, position GPS, photo du lieu), avec possibilité de joindre plusieurs fichiers (rapport de visite, etc.).', 8, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(19, 'MEPS_2026', '', 'MEPS_PRCO_1', 'RÉCUPÉRATION DE LA LISTE DES PROJETS', 'DOSSIER_RECUPERE', 'NON', 'Récupération de la liste des projets sélectionnés et pour lesquels les promoteurs ont été formés. Liste disponible pour tous les profils de l\'AEJ. Le rattachement à l\'agence régionale est récupéré via l\'API mise à disposition, ou à défaut déduit de la localisation du projet par région.', 1, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(20, 'MEPS_2026', '', 'MEPS_PRCO_2', 'TRANSMISSION AU PARTENAIRE FINANCIER', 'TRANSMIS_PARTENAIRE', 'NON', 'Le chef de service développement des ressources de financement (ou un agent du service) ajoute le plan d\'affaires puis transmet les dossiers par lot via un fichier Excel qui répartit les projets entre partenaires. Le courrier de transmission est joint et certaines de ses informations (référence, titre, date, taux de couverture, durée du différé, durée du remboursement, réf. de la convention) sont extraites et affichées sur chaque ligne de projet.', 2, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(21, 'MEPS_2026', '', 'MEPS_PRCO_3', 'IMPUTATION DES DOSSIERS APPROUVÉS AUX AGENCES RÉGIONALES', 'IMPUTE_AGENCE', 'NON', 'Sur la base des dossiers approuvés par le partenaire financier, le chef de service financement et monitoring impute certains dossiers aux agences régionales selon leur localisation. Les dossiers restants non imputés sont gérés directement par la Direction pour la saisie des plans de décaissement.', 3, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(22, 'MEPS_2026', '', 'MEPS_PRCO_4', 'SAISIE DES PLANS DE DÉCAISSEMENT PAR LES CIP DES AGENCES RÉGIONALES', 'PLAN_DECAISSEMENT_SAISI', 'NON', 'Le conseiller en insertion professionnelle (ou un agent de la direction pour les dossiers non imputés) remplit les plans de décaissement des bénéficiaires, avec possibilité d\'ajouter une note ou observation, et joint le fichier PDF du plan de décaissement signé par le bénéficiaire. Le plan de décaissement est partagé au bénéficiaire qui le valide via l\'application mobile.', 4, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(23, 'MEPS_2026', '', 'MEPS_PRCO_5', 'TRANSMISSION DES DOSSIERS AVEC LES PLANS DE DÉCAISSEMENT SAISIS', 'EN_VALIDATION_INTERNE', 'NON', 'Chaîne de validation interne du plan de décaissement avant transmission au partenaire financier.', 5, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(24, 'MEPS_2026', '', 'MEPS_PRCO_6', 'TRAITEMENT DES DOSSIERS PAR LE PARTENAIRE', 'EN_ANALYSE_PARTENAIRE', 'NON', 'Le partenaire financier renseigne, par saisie directe ou import Excel, les informations du lot de dossiers (date d\'ouverture du compte, approbation ou non, montant du crédit, durée du prêt, taux d\'intérêt, durée du remboursement), ajoute le tableau d\'amortissement (import possible) et une copie du contrat/convention de prêt en pièce jointe. Les dossiers approuvés et rejetés sont collectés dans deux listes distinctes puis renvoyés au chef de service développement des ressources de financement. Un outil de recherche permet à toute agence ou agent de l\'AEJ de retrouver un dossier par nom, téléphone ou N° de dossier du bénéficiaire.', 6, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
