(31, 'MENTORAT_2026', '', 'MENT_PRCO_7', 'SUIVI DE L’ACCOMPAGNEMENT', 'EN_SUIVI', 'NON', 'Le suivi de l\'accompagnement', 2, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(32, 'PERMIS_2026', '', 'PERM_PRCO_1', 'VISITE MEDICALE', 'EN_SUIVI', 'NON', 'La visite médicale', 1, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(33, 'PERMIS_2026', '', 'PERM_PRCO_2', 'FORMATION ET LE SUIVI DECENTRALISE DE LA MISE EN OEUVRE ', 'EN_FORMATION', 'NON', 'La formation et le suivi décentralisé de la mise en œuvre', 2, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(34, 'STARTUP_BOOST_2026', '', 'START_PRCO_1', 'RÉCUPÉRATION DE LA LISTE DES PROJETS CERTIFIÉS', 'DOSSIER_RECUPERE', 'NON', 'Récupération de la liste des projets certifiés. Liste disponible pour tous les profils de l\'AEJ. Le rattachement à l\'agence régionale est récupéré via l\'API mise à disposition, ou à défaut déduit de la localisation du projet par région.', 1, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(35, 'STARTUP_BOOST_2026', '', 'START_PRCO_2', 'TRANSMISSION AU PARTENAIRE FINANCIER', 'TRANSMIS_PARTENAIRE', 'NON', 'Le chef de service développement des ressources de financement (ou un agent du service) ajoute le nouveau plan d\'affaires puis transmet les dossiers par lot via un fichier Excel qui répartit les projets entre partenaires. Le courrier de transmission est joint et certaines de ses informations (référence, titre, date, taux de couverture, durée du différé, durée du remboursement, réf. de la convention) sont extraites et affichées sur chaque ligne de projet.', 2, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(36, 'STARTUP_BOOST_2026', '', 'START_PRCO_3', 'SAISIE DU PLAN DE DÉCAISSEMENT ET AJOUT DE LA CONVENTION DE PRÊT', 'EN_FINANCEMENT', 'NON', 'Deux actions menées en parallèle une fois les dossiers approuvés par le partenaire financier.', 3, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(37, 'STARTUP_BOOST_2026', '', 'START_PRCO_4', 'TRANSMISSION DES DOSSIERS AVEC LES PLANS DE DÉCAISSEMENT SAISIS', 'EN_VALIDATION_INTERNE', 'NON', 'Le CIP envoie les dossiers au chef d\'agence qui valide ou ajourne les plans de décaissement saisis, puis transmet les dossiers validés au chef de service développement des ressources de financement qui vérifie et soumet au sous-directeur de l\'évaluation financière, qui valide et soumet au sous-directeur du partenariat et financement, qui valide et soumet au Directeur du partenariat et financement, qui valide et transmet au partenaire financier.', 4, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(38, 'STARTUP_BOOST_2026', '', 'START_PRCO_5', 'TRAITEMENT DES DOSSIERS PAR LE PARTENAIRE', 'EN_ANALYSE_PARTENAIRE', 'NON', 'Le partenaire financier renseigne, par saisie directe ou import Excel, les informations du lot de dossiers (date d\'ouverture du compte, approbation ou non, montant du crédit, durée du prêt, taux d\'intérêt, durée du remboursement), ajoute le tableau d\'amortissement (import possible) et une copie du contrat/convention de prêt en pièce jointe. Les dossiers approuvés et rejetés sont collectés dans deux listes distinctes puis renvoyés au chef de service développement des ressources de financement.', 5, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(39, 'STARTUP_BOOST_2026', '', 'START_PRCO_6', 'DÉCAISSEMENT / REMBOURSEMENT', 'EN_FINANCEMENT', 'NON', 'Décaissement autorisé par le partenaire puis exécuté par les agences régionales, et suivi des remboursements.', 6, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(40, 'STARTUP_BOOST_2026', '', 'START_PRCO_7', 'SUIVI', 'EN_SUIVI', 'NON', 'Une fois le premier décaissement effectué, les agences régionales et la DPF réalisent des visites de suivi (date de la visite, état du projet, difficultés, recommandations, position GPS, photo du lieu), avec possibilité de joindre plusieurs fichiers (rapport de visite, etc.).', 7, 1, '2026-08-03', NULL, '2026-08-03 19:09:42', '2026-08-03 19:09:42'),
(42, 'AGR_CLASSIQUE_2026', NULL, 'SPRTY', 'Finition', 'MARCCHINALE', 'NON', 'La description de mon etape', 7, 1, '2026-08-03', NULL, '2026-08-15 18:11:03', '2026-08-15 18:11:03'),
(43, 'AGR_CLASSIQUE_2026', NULL, 'tezta', 'testqw sd', NULL, 'NON', NULL, 8, 1, '2026-08-03', NULL, '2026-08-20 16:35:56', '2026-08-20 17:25:18'),
(46, 'AGR_CLASSIQUE_Version Younouss', NULL, 'etape 1', 'etape 1 de test', NULL, 'NON', NULL, 1, 1, '2026-08-03', NULL, '2026-08-25 19:02:10', '2026-08-25 19:02:10'),
(47, 'AGR_CLASSIQUE_Version Younouss', NULL, 'etape 2', 'etape 2 nom', NULL, 'NON', NULL, 2, 1, '2026-08-03', NULL, '2026-08-25 21:38:57', '2026-08-25 21:38:57'),
(48, 'AGR_CLASSIQUE_Version Younouss', 'etape 1', 'c001', 'sous etape 2', NULL, 'NON', NULL, 1, 1, '2026-08-03', NULL, '2026-08-25 22:00:05', '2026-08-25 22:00:05');

